ALTER TABLE admin_access_audit ADD COLUMN grant_revision integer CHECK(grant_revision>0),ADD COLUMN grant_permissions text[] CHECK(grant_permissions IS NULL OR (cardinality(grant_permissions) BETWEEN 1 AND 4 AND grant_permissions <@ ARRAY['users.read','workspaces.read','jobs.read','consumption.read']::text[] AND array_position(grant_permissions,NULL) IS NULL)),ADD COLUMN grant_workspace_ids uuid[] CHECK(grant_workspace_ids IS NULL OR (cardinality(grant_workspace_ids) BETWEEN 1 AND 50 AND array_position(grant_workspace_ids,NULL) IS NULL));
